const input = $json.body ?? $json;
const expectedStages = ['chat','workflows','code','projects','skills'];
const next = {chat:'workflows',workflows:'code',code:'projects',projects:'skills',skills:'chat'};
const requiredEvidence = new Set(['code:projects','projects:skills','skills:chat']);
const skillRoutes = {
  chat:['intent-repair-reader','capability-mode-router'],
  workflows:['lean-build-orchestrator','capability-mode-router'],
  code:['lean-build-orchestrator','regression-stagnation-guard','capability-mode-router'],
  projects:['regression-stagnation-guard','truth-research-optimizer'],
  skills:['truth-research-optimizer','capability-mode-router']
};
const fail = (reason) => { throw new Error(reason); };
if (input.contract !== 'founder-control-room/n8n-conveyor@v1') fail('invalid contract');
if (input.event !== 'conveyor.stage.advance') fail('invalid event');
if (!/^fcr-conveyor-v1:[0-9a-f]{64}$/i.test(input.idempotencyKey ?? '')) fail('invalid idempotency key');
if (!/^[0-9a-f]{40}$/i.test(input.expectedHeadSha ?? '')) fail('expectedHeadSha must be exact');
if (!expectedStages.includes(input.fromStage) || !expectedStages.includes(input.toStage)) fail('invalid stage');
if (next[input.fromStage] !== input.toStage) fail('invalid stage transition');
if (requiredEvidence.has(`${input.fromStage}:${input.toStage}`) && (!Array.isArray(input.evidenceUrls) || input.evidenceUrls.length === 0)) fail('evidence required');
const authority = input.authority ?? {};
if (authority.advanceStage !== true || authority.merge !== false || authority.deploy !== false || authority.publish !== false || authority.sendExternal !== false) fail('authority envelope rejected');
const skillIds = skillRoutes[input.toStage];
const receiptSeed = [input.idempotencyKey,input.runId,input.projectSlug,input.fromStage,input.toStage,input.expectedHeadSha,...skillIds].join(':');
return [{json:{accepted:true,receiptSeed,runId:input.runId,projectSlug:input.projectSlug,fromStage:input.fromStage,toStage:input.toStage,expectedHeadSha:input.expectedHeadSha,evidenceUrls:input.evidenceUrls ?? [],skillIds}}];

const crypto = require('crypto');
const receiptId = `fcr-n8n-v1:${crypto.createHash('sha256').update($json.receiptSeed).digest('hex')}`;
return [{json:{receiptId,status:'accepted',runId:$json.runId,projectSlug:$json.projectSlug,fromStage:$json.fromStage,toStage:$json.toStage,expectedHeadSha:$json.expectedHeadSha,skillIds:$json.skillIds,evidenceUrls:$json.evidenceUrls}}];
